// Domain types for the Companies feature.
// Mirrors the backend Prisma `Company` model (backend/prisma/schema.prisma).
//
// API boundary notes (for when the companies API is wired up):
//   name        -> Company.name  (backend also derives normalizedName for
//                  duplicate checks, so the client never sends it)
//   website/industry/phone/address/city/state/country/notes -> same fields
//   contactCount -> derived from the related Contact[] relation (see below)
//   id/createdAt/updatedAt -> generated by the database

export type Company = {
  id: number;
  /** Company.name */
  name: string;
  website: string;
  industry: string;
  phone: string;
  /** Company.address — free-text street address. */
  address: string;
  city: string;
  state: string;
  country: string;
  notes: string;
  /**
   * Number of related contacts. On the API this is `Company._count.contacts`;
   * here it is derived by matching contact.company against Company.name.
   */
  contactCount: number;
  /** ISO date strings (Company.createdAt / updatedAt). */
  createdAt: string;
  updatedAt: string;
};

/** Fields the create/edit form collects. */
export type CompanyFormValues = {
  name: string;
  website: string;
  industry: string;
  phone: string;
  address: string;
  city: string;
  state: string;
  country: string;
  notes: string;
};

/** Canonical industry list, shared with the lead form's Company section. */
export const COMPANY_INDUSTRIES: string[] = [
  "Technology",
  "Finance",
  "Healthcare",
  "Manufacturing",
  "Retail",
  "Education",
  "Other",
];
